// ── idle (solo_nonpath) ──

export class Idle extends SoloVerb {
  constructor() {
    super('idle');
    this._driftRadius = 6;
    this._loopSeconds = 4;
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (entity._idleAnchorX == null) {
      entity._idleAnchorX = entity.x;
      entity._idleAnchorY = entity.y;
      entity._idlePath = this._buildLoop(entity._idleAnchorX, entity._idleAnchorY);
    }

    const path = entity._idlePath;
    const defaultSpeed = path.totalLength / this._loopSeconds;
    const speed = this._adverbSpeed ?? defaultSpeed;
    const elapsed = entity._stateElapsed - (this._wait ?? 0);
    if (elapsed < 0) return;

    const loopDur = path.totalLength / speed;
    let t = (elapsed % loopDur) / loopDur;

    if (this._easing) t = this._easing(t);

    const accel = this._accelerationFn ? this._accelerationFn(t) : 1;
    const effectiveSpeed = speed * accel;
    const dist = t * path.totalLength;
    const pt = path.sampleAt(dist);

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(t);
      ox = pt.nx * d;
      oy = pt.ny * d;
    }

    entity.vx = pt.tx * effectiveSpeed;
    entity.vy = pt.ty * effectiveSpeed;
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  _buildLoop(cx, cy) {
    const r = this._driftRadius;
    const N = 48;
    const points = [];
    for (let i = 0; i <= N; i++) {
      const a = (i / N) * Math.PI * 2;
      points.push({
        x: cx + r * Math.sin(a),
        y: cy + r * Math.sin(a * 2) * 0.5
      });
    }
    return new Path(points);
  }

  cleanup(entity) {
    entity._idleAnchorX = null;
    entity._idleAnchorY = null;
    entity._idlePath = null;
  }
}


