// ── struggle (solo_nonpath) ──

export class Struggle extends SoloVerb {
  constructor() {
    super('struggle');
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (!entity._strugglePath) {
      const sx = entity.x, sy = entity.y;
      const ang = Math.random() * Math.PI * 2;
      const d = 150 + Math.random() * 100;
      const ex = Math.max(50, Math.min(462, sx + Math.cos(ang) * d));
      const ey = Math.max(50, Math.min(462, sy + Math.sin(ang) * d));
      entity._strugglePath = BezierPath.fromEndpoints(
        { x: sx, y: sy }, { x: ex, y: ey },
        { perpOffset: 0.2, side: Math.random() < 0.5 ? 1 : -1 }
      );
      entity._struggleDist = 0;
      entity._strugglePhase = Math.random() * Math.PI * 2;
    }

    const path = entity._strugglePath;
    const len = path.totalLength;
    const baseSpeed = this._adverbSpeed ?? 50;
    const elapsed = entity._stateElapsed ?? 0;
    const normT = Math.min(entity._struggleDist / len, 1);
    const accel = this._accelerationFn ? this._accelerationFn(normT) : 1;
    const p = entity._strugglePhase;

    const surge = Math.sin(elapsed * 3.2 + p) * 0.5
               + Math.sin(elapsed * 7.9 + p * 1.7) * 0.35
               + Math.sin(elapsed * 13.6 + p * 0.5) * 0.2;
    const speed = baseSpeed * accel * Math.max(-0.2, 0.25 + surge);

    entity._struggleDist = Math.max(0, Math.min(entity._struggleDist + speed * dt, len));
    let ratio = entity._struggleDist / len;
    if (this._easing) ratio = this._easing(ratio);

    if (entity._struggleDist >= len) {
      const end = path.sampleAt(len);
      entity.x = end.x; entity.y = end.y;
      entity.vx = 0; entity.vy = 0;
      return;
    }

    const pt = path.sampleAt(ratio * len);
    const tremor = Math.sin(elapsed * 22 + p) * 3.5 + Math.sin(elapsed * 37 + p * 2) * 1.5;
    const offAdv = this._offsetFn ? this._offsetFn(ratio) : 0;
    const fx = pt.x + pt.nx * (tremor + offAdv);
    const fy = pt.y + pt.ny * (tremor + offAdv);

    entity.vx = pt.tx * speed;
    entity.vy = pt.ty * speed;
    entity.x = fx - entity.vx * dt;
    entity.y = fy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._strugglePath = null;
    entity._struggleDist = null;
    entity._strugglePhase = null;
  }
}


