// ── wander (solo_nonpath) ──

export class Wander extends SoloVerb {
  constructor() {
    super('wander');
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (!entity._wanderPath || entity._wanderT >= 1) {
      this._generatePath(entity);
    }

    const path = entity._wanderPath;
    if (!path) return;

    const speed = this._adverbSpeed ?? 70;
    const baseDuration = path.totalLength / speed;
    const accel = this._accelerationFn ? this._accelerationFn(entity._wanderT) : 1;
    const effectiveSpeed = speed * accel;

    entity._wanderT = Math.min(entity._wanderT + (dt * accel) / baseDuration, 1);

    const t = this._easing ? this._easing(entity._wanderT) : entity._wanderT;
    const dist = t * path.totalLength;
    const pt = path.sampleAt(dist);

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(t);
      ox = pt.nx * d;
      oy = pt.ny * d;
    }

    entity.vx = pt.tx * effectiveSpeed;
    entity.vy = pt.ty * effectiveSpeed;
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
    entity.orientation = Math.atan2(pt.ty, pt.tx);
  }

  _generatePath(entity) {
    const margin = 40;
    const minDist = 80;
    const maxDist = 180;
    const sx = entity.x;
    const sy = entity.y;

    let dx, dy, attempts = 0;
    do {
      const angle = Math.random() * Math.PI * 2;
      const r = minDist + Math.random() * (maxDist - minDist);
      dx = sx + Math.cos(angle) * r;
      dy = sy + Math.sin(angle) * r;
      attempts++;
    } while (
      attempts < 12 &&
      (dx < margin || dx > 512 - margin || dy < margin || dy > 512 - margin)
    );

    dx = Math.max(margin, Math.min(512 - margin, dx));
    dy = Math.max(margin, Math.min(512 - margin, dy));

    entity._wanderPath = BezierPath.fromEndpoints(
      { x: sx, y: sy },
      { x: dx, y: dy },
      { perpOffset: 0.1 + Math.random() * 0.3, side: Math.random() < 0.5 ? 1 : -1 }
    );
    entity._wanderT = 0;
  }

  cleanup(entity) {
    entity._wanderPath = null;
    entity._wanderT = null;
  }
}


// ── bounce (solo_nonpath) ──

export class Bounce extends SoloVerb {
  constructor() {
    super('bounce');
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (entity._bounceStartX == null) {
      entity._bounceStartX = entity.x;
      entity._bounceStartY = entity.y;
      entity._bounceAngle = entity.orientation ?? 0;
      this._buildArcs(entity);
    }

    const elapsed = entity._stateElapsed - (this._wait ?? 0);
    if (elapsed < 0) return;

    const totalDur = entity._bounceTotalDur;
    const rawT = Math.min(elapsed / totalDur, 1);
    const t = this._easing ? this._easing(rawT) : rawT;
    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;
    const speed = (this._adverbSpeed ?? 80) * accel;
    const time = t * totalDur;

    const arcs = entity._bounceArcs;
    let arcTime = time;
    let ai = arcs.length - 1;
    for (let i = 0; i < arcs.length; i++) {
      if (arcTime <= arcs[i].dur) { ai = i; break; }
      arcTime -= arcs[i].dur;
    }
    arcTime = Math.min(arcTime, arcs[ai].dur);

    const G = 900;
    const vy0 = arcs[ai].vy0;
    const loft = vy0 * arcTime + 0.5 * G * arcTime * arcTime;
    const loftClamped = Math.min(loft, 0);

    const hDist = speed * time;
    const angle = entity._bounceAngle;
    const perpX = -Math.sin(angle);
    const perpY = Math.cos(angle);

    let tx = entity._bounceStartX + Math.cos(angle) * hDist + perpX * loftClamped;
    let ty = entity._bounceStartY + Math.sin(angle) * hDist + perpY * loftClamped;

    if (this._offsetFn) {
      const off = this._offsetFn(rawT);
      tx += perpX * off;
      ty += perpY * off;
    }

    if (rawT >= 1) {
      entity.x = tx;
      entity.y = ty;
      entity.vx = 0;
      entity.vy = 0;
      return;
    }

    const vyNow = vy0 + G * arcTime;
    entity.vx = Math.cos(angle) * speed + perpX * vyNow;
    entity.vy = Math.sin(angle) * speed + perpY * vyNow;
    entity.x = tx - entity.vx * dt;
    entity.y = ty - entity.vy * dt;
  }

  _buildArcs(entity) {
    const G = 900;
    const restitution = 0.6;
    const numBounces = 5;
    let vy = -350;
    const arcs = [];
    let total = 0;
    for (let i = 0; i < numBounces; i++) {
      const dur = -2 * vy / G;
      arcs.push({ vy0: vy, dur });
      total += dur;
      vy *= restitution;
    }
    entity._bounceArcs = arcs;
    entity._bounceTotalDur = total;
  }

  cleanup(entity) {
    entity._bounceStartX = null;
    entity._bounceStartY = null;
    entity._bounceAngle = null;
    entity._bounceArcs = null;
    entity._bounceTotalDur = null;
  }
}


// ── walk (solo_path) ──

export class Walk extends PathMotion {
  constructor(path, duration) {
    const defaultSpeed = 90;
    const computedDuration = path
      ? (duration ?? (path.totalLength / defaultSpeed))
      : (duration ?? 1);
    super('walk', path ?? null, computedDuration);

    this._walkDefaultSpeed = defaultSpeed;
    this._stepFreq = 2.8;
    this._bobAmount = 2.5;
  }

  update(entity, dt) {
    if (!this.path) {
      this._buildDefaultPath(entity);
    }

    const elapsed = entity._stateElapsed ?? 0;

    if (this._wait && elapsed < this._wait) {
      entity.vx = 0;
      entity.vy = 0;
      return;
    }

    if (this._adverbSpeed) {
      this.setSpeed(this._adverbSpeed);
    }

    super.update(entity, dt);

    if (!this._arrived) {
      const spd = Math.hypot(entity.vx, entity.vy);
      if (spd > 0.1) {
        const bobDisp = Math.sin(elapsed * this._stepFreq * Math.PI * 2) * this._bobAmount;
        const nx = -entity.vy / spd;
        const ny = entity.vx / spd;
        entity.x += nx * bobDisp;
        entity.y += ny * bobDisp;
        entity.orientation = Math.atan2(entity.vy, entity.vx);
      }
    }

    entity._walkPhase = (elapsed * this._stepFreq) % 1;
  }

  _buildDefaultPath(entity) {
    const margin = 60;
    const sx = entity.x;
    const sy = entity.y;
    const angle = entity.orientation ?? 0;
    const dist = 220;
    const ex = Math.max(margin, Math.min(512 - margin, sx + Math.cos(angle) * dist));
    const ey = Math.max(margin, Math.min(512 - margin, sy + Math.sin(angle) * dist));
    this.path = BezierPath.fromEndpoints(
      { x: sx, y: sy },
      { x: ex, y: ey },
      { perpOffset: 0.05, side: 1 }
    );
    this.duration = this.path.totalLength / (this._adverbSpeed ?? this._walkDefaultSpeed);
  }

  cleanup(entity) {
    entity._walkPhase = null;
  }
}


// ── spiral (solo_path) ──

export class Spiral extends PathMotion {
  constructor(path, duration = 3, { revolutions = 3, maxRadius = 100 } = {}) {
    super('spiral', null, duration);
    this._revolutions = revolutions;
    this._maxRadius = maxRadius;
  }

  update(entity, dt) {
    if (!this.path) {
      this._buildPath(entity);
    }
    super.update(entity, dt);
  }

  _buildPath(entity) {
    const cx = entity.x;
    const cy = entity.y;
    entity._spiralCenterX = cx;
    entity._spiralCenterY = cy;

    const revs = this._revolutions;
    // Scale radius to canvas size so spiral is visually proportional
    const canvasMin = entity._bounds
      ? Math.min(entity._bounds.right - entity._bounds.left, entity._bounds.bottom - entity._bounds.top)
      : 160;

    const maxR = canvasMin * 0.4;
    const startAngle = entity.orientation ?? 0;
    const totalAngle = revs * Math.PI * 2;
    const numPoints = Math.max(80, Math.round(revs * 48));
    const points = [];

    for (let i = 0; i <= numPoints; i++) {
      const t = i / numPoints;
      const angle = startAngle + t * totalAngle;
      const r = t * maxR;
      points.push({
        x: cx + r * Math.cos(angle),
        y: cy + r * Math.sin(angle)
      });
    }

    this.path = new Path(points);

    const speed = this._adverbSpeed;
    if (speed) {
      this.duration = this.path.totalLength / speed;
    }
  }

  cleanup(entity) {
    entity._spiralCenterX = null;
    entity._spiralCenterY = null;
  }
}


// ── zigzag (solo_path) ──

export class Zigzag extends PathMotion {
  constructor(path, duration, { segments = 6, amplitude = 50 } = {}) {
    super('zigzag', path ?? null, duration ?? 2.5);
    this._zigSegments = segments;
    this._zigAmplitude = amplitude;
    this._zigReady = false;
  }

  update(entity, dt) {
    if (!this._zigReady) {
      this._buildPath(entity);
      this._zigReady = true;
    }
    super.update(entity, dt);
  }

  _buildPath(entity) {
    const segs = this._zigSegments;
    const amp = this._zigAmplitude;
    const speed = this._adverbSpeed ?? 160;
    const margin = entity.radius + 4;

    const sx = entity.x;
    const sy = entity.y;
    const angle = entity.orientation ?? (Math.random() * Math.PI * 2);
    const travel = 240;

    const ex = sx + Math.cos(angle) * travel;
    const ey = sy + Math.sin(angle) * travel;

    const px = -Math.sin(angle);
    const py = Math.cos(angle);

    const clamp = (v) => Math.max(margin, Math.min(512 - margin, v));

    const points = [{ x: sx, y: sy }];
    for (let i = 1; i <= segs; i++) {
      const frac = i / (segs + 1);
      const side = (i % 2 === 1) ? 1 : -1;
      const bx = sx + (ex - sx) * frac;
      const by = sy + (ey - sy) * frac;
      points.push({
        x: clamp(bx + px * amp * side),
        y: clamp(by + py * amp * side)
      });
    }
    points.push({ x: clamp(ex), y: clamp(ey) });

    this.path = new Path(points);
    this.duration = this.path.totalLength / speed;
  }

  cleanup(entity) {
    // No per-entity state stored on entity
  }
}


// ── pace (solo_path) ──

export class Pace extends PathMotion {
  constructor() {
    super('pace', null, 1);
    this._pauseEnd = 0.28;
  }

  update(entity, dt) {
    if (!this.path) {
      const speed = this._adverbSpeed ?? 85;
      const angle = entity._paceAngle = Math.random() * Math.PI;
      const half = 70;
      const s = { x: entity.x - Math.cos(angle) * half, y: entity.y - Math.sin(angle) * half };
      const e = { x: entity.x + Math.cos(angle) * half, y: entity.y + Math.sin(angle) * half };
      this.path = BezierPath.fromEndpoints(s, e, { perpOffset: 0.04, side: 1 });
      this.duration = this.path.totalLength / speed;
    }

    const wEnter = this._wait ?? 0;
    const elapsed = (entity._stateElapsed ?? 0) - wEnter;
    if (elapsed < 0) { entity.vx = 0; entity.vy = 0; return; }

    const pause = this._pauseEnd;
    const leg = this.duration + pause;
    const pos = elapsed % (leg * 2);
    let rawT, dir;
    if (pos < this.duration)            { rawT = pos / this.duration; dir = 1; }
    else if (pos < leg)                 { rawT = 1; dir = 0; }
    else if (pos < leg + this.duration) { rawT = 1 - (pos - leg) / this.duration; dir = -1; }
    else                                { rawT = 0; dir = 0; }

    const easedT = this._easing ? this._easing(rawT) : rawT;
    const dist = easedT * this.path.totalLength;
    const pt = this.path.sampleAt(dist);

    if (dir === 0) {
      entity.x = pt.x; entity.y = pt.y;
      entity.vx = 0; entity.vy = 0;
      return;
    }

    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;
    const spd = (this.path.totalLength / this.duration) * accel * dir;
    entity.vx = pt.tx * spd;
    entity.vy = pt.ty * spd;
    entity.orientation = Math.atan2(entity.vy, entity.vx);

    let ox = 0, oy = 0;
    if (this._offsetFn) { const d = this._offsetFn(easedT); ox = pt.nx * d; oy = pt.ny * d; }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._paceAngle = null;
  }
}


// ── glide (solo_path) ──

export class Glide extends PathMotion {
  constructor(path, duration) {
    super('glide', path, duration || 2.5);
    this._needsPath = !path;
    if (!this._easing) {
      this._easing = t => t < 0.5
        ? 2 * t * t
        : 1 - Math.pow(-2 * t + 2, 2) / 2;
    }
  }

  _generatePath(entity) {
    entity._glideOriginX = entity.x;
    entity._glideOriginY = entity.y;

    const speed = this._adverbSpeed ?? 120;
    const dist = speed * this.duration;
    const angle = entity.orientation ?? Math.random() * Math.PI * 2;

    let destX = entity.x + Math.cos(angle) * dist;
    let destY = entity.y + Math.sin(angle) * dist;

    const margin = entity.radius + 24;
    destX = Math.max(margin, Math.min(512 - margin, destX));
    destY = Math.max(margin, Math.min(512 - margin, destY));

    const side = Math.random() < 0.5 ? 1 : -1;
    this.path = BezierPath.fromEndpoints(
      { x: entity.x, y: entity.y },
      { x: destX, y: destY },
      { perpOffset: 0.12, side }
    );

    this.duration = this.path.totalLength / speed;
  }

  update(entity, dt) {
    if (this._needsPath) {
      this._generatePath(entity);
      this._needsPath = false;
    }

    if (this._wait && (entity._stateElapsed ?? 0) < this._wait) {
      entity.vx = 0;
      entity.vy = 0;
      return;
    }

    super.update(entity, dt);
  }

  cleanup(entity) {
    entity._glideOriginX = null;
    entity._glideOriginY = null;
  }
}


// ── dart (solo_path) ──

export class Dart extends PathMotion {
  constructor(path, duration) {
    const dartPath = path || Dart._generatePath();
    const defaultSpeed = 500;
    const defaultDuration = duration || (dartPath.totalLength / defaultSpeed);
    super('dart', dartPath, defaultDuration);

    if (!this._easing) {
      this._easing = (t) => {
        const t1 = 1 - t;
        return 1 - t1 * t1 * t1;
      };
    }
  }

  static _generatePath() {
    const margin = 60;
    const cx = 256;
    const cy = 256;
    const angle = Math.random() * Math.PI * 2;
    const dartLength = 80 + Math.random() * 100;
    const startX = cx + (Math.random() - 0.5) * 200;
    const startY = cy + (Math.random() - 0.5) * 200;
    const endX = startX + Math.cos(angle) * dartLength;
    const endY = startY + Math.sin(angle) * dartLength;
    const clamp = (v) => Math.max(margin, Math.min(512 - margin, v));
    return BezierPath.fromEndpoints(
      { x: clamp(startX), y: clamp(startY) },
      { x: clamp(endX), y: clamp(endY) },
      { perpOffset: 0.05 + Math.random() * 0.1, side: Math.random() < 0.5 ? 1 : -1 }
    );
  }

  update(entity, dt) {
    if (this._wait && (entity._stateElapsed ?? 0) < this._wait) {
      entity.vx = 0;
      entity.vy = 0;
      return;
    }

    if (this._adverbSpeed != null) {
      this.setSpeed(this._adverbSpeed);
    }

    if (entity._dartStartX == null) {
      entity._dartStartX = entity.x;
      entity._dartStartY = entity.y;

      if (this.path && this.path.sampleAt) {
        const startPt = this.path.sampleAt(0);
        entity.x = startPt.x;
        entity.y = startPt.y;
      }
    }

    super.update(entity, dt);

    if (this._offsetFn && !this._arrived) {
      const elapsed = entity._stateElapsed ?? 0;
      const wEnter = this._waitEnter ?? 0;
      const rawT = Math.min(Math.max((elapsed - wEnter) / this.duration, 0), 1);
      const t = this._easing ? this._easing(rawT) : rawT;
      const perpDisp = this._offsetFn(t);
      const distance = t * this.path.totalLength;
      const point = this.path.sampleAt(distance);
      entity.x += point.nx * perpDisp - entity.vx * dt;
      entity.y += point.ny * perpDisp - entity.vy * dt;
    }
  }

  cleanup(entity) {
    entity._dartStartX = null;
    entity._dartStartY = null;
  }
}


// ── swoop (solo_path) ──

export class Swoop extends PathMotion {
  constructor(path, duration) {
    super('swoop', path, duration ?? 1.0);
    this._pathReady = !!path;
    this._swoopDefaultAccel = t => 0.3 + 2.8 * Math.sin(Math.PI * t);
    if (!this._easing) {
      this.setAcceleration(this._swoopDefaultAccel);
    }
  }

  update(entity, dt) {
    if (!this._pathReady) {
      this._buildDefaultPath(entity);
      this._pathReady = true;
    }

    super.update(entity, dt);

    if (Math.abs(entity.vx) > 0.5 || Math.abs(entity.vy) > 0.5) {
      entity.orientation = Math.atan2(entity.vy, entity.vx);
    }
  }

  _buildDefaultPath(entity) {
    const sx = entity.x;
    const sy = entity.y;
    const angle = entity.orientation ?? -Math.PI * 0.25;
    const reach = 250;
    const ex = Math.max(50, Math.min(462, sx + Math.cos(angle) * reach));
    const ey = Math.max(50, Math.min(462, sy + Math.sin(angle) * reach));

    const crossAngle = angle + Math.PI * 0.5;
    const crossComponent = Math.sin(crossAngle);
    const side = crossComponent >= 0 ? 1 : -1;

    this.path = BezierPath.fromEndpoints(
      { x: sx, y: sy },
      { x: ex, y: ey },
      { perpOffset: 0.45, side }
    );

    if (this._adverbSpeed) {
      this.duration = this.path.totalLength / this._adverbSpeed;
    }
  }

  cleanup(entity) {
    this._pathReady = false;
  }
}


// ── lunge (solo_path) ──

export class Lunge extends PathMotion {
  constructor() {
    super('lunge', null, 0.35);
    this._initialized = false;
  }

  update(entity, dt) {
    if (!this._initialized) {
      this._initialized = true;

      const defaultSpeed = 450;
      const speed = this._adverbSpeed ?? defaultSpeed;
      const lungeDistance = Math.min(speed * 0.35, 200);

      let angle;
      if (entity._target) {
        const dx = entity._target.x - entity.x;
        const dy = entity._target.y - entity.y;
        angle = Math.atan2(dy, dx);
      } else {
        angle = entity.orientation || 0;
      }

      let endX = entity.x + Math.cos(angle) * lungeDistance;
      let endY = entity.y + Math.sin(angle) * lungeDistance;
      const r = entity.radius;
      endX = Math.max(r, Math.min(512 - r, endX));
      endY = Math.max(r, Math.min(512 - r, endY));

      entity._lungeStartX = entity.x;
      entity._lungeStartY = entity.y;
      entity._lungeAngle = angle;

      this.path = BezierPath.fromEndpoints(
        { x: entity.x, y: entity.y },
        { x: endX, y: endY },
        { perpOffset: 0.04, side: Math.random() < 0.5 ? 1 : -1 }
      );

      this.duration = this.path.totalLength / speed;

      if (!this._easing && !this._accelerationFn) {
        this.setAcceleration(t => Math.max(0.05, (1 - t * t) * 2.8));
      }

      entity.orientation = angle;
    }

    super.update(entity, dt);

    if (!this._arrived) {
      entity.orientation = entity._lungeAngle ?? entity.orientation;
    }
  }

  cleanup(entity) {
    entity._lungeStartX = null;
    entity._lungeStartY = null;
    entity._lungeAngle = null;
    this._initialized = false;
  }
}


// ── follow (relational_nonpath) ──

export class Follow extends RelationalVerb {
  constructor() {
    super('follow', { gap: 12, collision: 'stop' });
  }

  _sampleTrail(trail, dist) {
    let rem = dist, px = trail[0].x, py = trail[0].y, tdx = 0, tdy = 0;
    for (let i = 1; i < trail.length; i++) {
      const dx = trail[i].x - trail[i - 1].x, dy = trail[i].y - trail[i - 1].y;
      const slen = Math.hypot(dx, dy);
      if (slen < 0.001) continue;
      tdx = dx / slen; tdy = dy / slen;
      if (rem <= slen) {
        const f = rem / slen;
        return { x: trail[i - 1].x + dx * f, y: trail[i - 1].y + dy * f, tx: tdx, ty: tdy };
      }
      rem -= slen; px = trail[i].x; py = trail[i].y;
    }
    return { x: px, y: py, tx: tdx, ty: tdy };
  }

  update(entity, dt) {
    const tgt = entity._target;
    if (!tgt) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (!entity._followTrail) {
      entity._followTrail = [{ x: tgt.x, y: tgt.y }];
      entity._followLen = 0;
      entity._followPos = 0;
    }
    const trail = entity._followTrail;
    const last = trail[trail.length - 1];
    const seg = Math.hypot(tgt.x - last.x, tgt.y - last.y);
    if (seg > 4) { trail.push({ x: tgt.x, y: tgt.y }); entity._followLen += seg; }

    const speed = this._adverbSpeed ?? 150;
    const tNorm = entity._stateElapsed / (entity._stateDuration || 1);
    const accel = this._accelerationFn ? this._accelerationFn(tNorm) : 1;
    const goal = Math.max(0, entity._followLen - this.bubble(entity));
    const step = Math.min(speed * accel * dt, Math.max(0, goal - entity._followPos));
    entity._followPos += step;

    const pt = this._sampleTrail(trail, entity._followPos);
    let px = pt.x, py = pt.y;
    if (this._offsetFn) {
      const off = this._offsetFn(entity._followLen > 0 ? entity._followPos / entity._followLen : 0);
      px -= pt.ty * off; py += pt.tx * off;
    }

    const spd = dt > 0 ? step / dt : 0;
    entity.vx = pt.tx * spd; entity.vy = pt.ty * spd;
    entity.x = px - entity.vx * dt; entity.y = py - entity.vy * dt;
    this.lookAt(entity, dt, 12);

    let trim = 0, ti = 0;
    while (ti < trail.length - 2) {
      const sl = Math.hypot(trail[ti + 1].x - trail[ti].x, trail[ti + 1].y - trail[ti].y);
      if (trim + sl > entity._followPos - 8) break;
      trim += sl; ti++;
    }
    if (ti > 0) { trail.splice(0, ti); entity._followPos -= trim; entity._followLen -= trim; }
  }

  cleanup(entity) {
    entity._followTrail = null;
    entity._followLen = null;
    entity._followPos = null;
  }
}


// ── avoid (relational_nonpath) ──

export class Avoid extends RelationalVerb {
  constructor() {
    super('avoid', { gap: 50, collision: 'stop' });
  }

  _planPath(entity) {
    const t = entity._target;
    const dx = entity.x - t.x;
    const dy = entity.y - t.y;
    const dist = Math.hypot(dx, dy) || 1;
    const nx = dx / dist;
    const ny = dy / dist;
    const fleeLen = Math.max(100, this.bubble(entity) + 80 - dist);
    const margin = entity.radius + 12;
    let gx = Math.max(margin, Math.min(512 - margin, entity.x + nx * fleeLen));
    let gy = Math.max(margin, Math.min(512 - margin, entity.y + ny * fleeLen));
    if (Math.hypot(gx - entity.x, gy - entity.y) < 25) {
      gx = Math.max(margin, Math.min(512 - margin, entity.x - ny * fleeLen));
      gy = Math.max(margin, Math.min(512 - margin, entity.y + nx * fleeLen));
    }
    const cross = dx * (gy - entity.y) - dy * (gx - entity.x);
    const path = BezierPath.fromEndpoints(
      { x: entity.x, y: entity.y },
      { x: gx, y: gy },
      { perpOffset: 0.35, side: cross >= 0 ? 1 : -1 }
    );
    const speed = this._adverbSpeed ?? 170;
    entity._avoidPath = path;
    entity._avoidDur = path.totalLength / speed;
    entity._avoidT0 = entity._stateElapsed ?? 0;
    entity._avoidTgtX = t.x;
    entity._avoidTgtY = t.y;
  }

  _stale(entity) {
    if (!entity._avoidPath) return true;
    const t = entity._target;
    if (Math.hypot(t.x - entity._avoidTgtX, t.y - entity._avoidTgtY) > 55) return true;
    const el = (entity._stateElapsed ?? 0) - entity._avoidT0;
    return el >= entity._avoidDur;
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    this.lookAway(entity, dt, 10);
    const distToTarget = Math.hypot(t.x - entity.x, t.y - entity.y);
    const threatRange = this.bubble(entity) + 130;

    if (distToTarget > threatRange && (!entity._avoidPath || this._stale(entity))) {
      entity._avoidPath = null;
      this.resist(entity, dt, 5);
      return;
    }

    if (this._stale(entity)) this._planPath(entity);
    const path = entity._avoidPath;
    if (!path) return;

    const speed = this._adverbSpeed ?? 170;
    const globalT = entity._stateElapsed / (entity._stateDuration || 1);
    const accel = this._accelerationFn ? this._accelerationFn(globalT) : 1;
    const elapsed = (entity._stateElapsed ?? 0) - entity._avoidT0;
    let rawT = Math.min(elapsed / entity._avoidDur, 1);
    const easedT = this._easing ? this._easing(rawT) : rawT;
    const pt = path.sampleAt(easedT * path.totalLength);
    const v = speed * accel;
    entity.vx = pt.tx * v;
    entity.vy = pt.ty * v;
    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(easedT);
      ox = pt.nx * d;
      oy = pt.ny * d;
    }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._avoidPath = null;
    entity._avoidDur = null;
    entity._avoidT0 = null;
    entity._avoidTgtX = null;
    entity._avoidTgtY = null;
  }
}


// ── flee (relational_nonpath) ──

export class Flee extends RelationalVerb {
  constructor() {
    super('flee', { gap: 60, collision: 'none' });
  }

  _buildPath(entity) {
    const t = entity._target;
    if (!t) return null;
    const away = Math.atan2(entity.y - t.y, entity.x - t.x);
    const angle = away + (Math.random() - 0.5) * 1.0;
    const pad = entity.radius + 16;
    const dist = 180 + Math.random() * 120;
    const destX = Math.max(pad, Math.min(512 - pad, entity.x + Math.cos(angle) * dist));
    const destY = Math.max(pad, Math.min(512 - pad, entity.y + Math.sin(angle) * dist));
    const side = Math.random() < 0.5 ? 1 : -1;
    return BezierPath.fromEndpoints(
      { x: entity.x, y: entity.y },
      { x: destX, y: destY },
      { perpOffset: 0.1 + Math.random() * 0.2, side }
    );
  }

  update(entity, dt) {
    if (!entity._target) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 300;
    this.lookAway(entity, dt, 10);

    if (!entity._fleePath || entity._fleeArrived) {
      entity._fleePath = this._buildPath(entity);
      if (!entity._fleePath) return;
      entity._fleeStart = entity._stateElapsed;
      entity._fleeDur = entity._fleePath.totalLength / speed;
      entity._fleeArrived = false;
    }

    const col = this.detectCollision(entity);
    if (col?.hit && (entity._stateElapsed - entity._fleeStart) > entity._fleeDur * 0.25) {
      entity._fleePath = this._buildPath(entity);
      if (!entity._fleePath) return;
      entity._fleeStart = entity._stateElapsed;
      entity._fleeDur = entity._fleePath.totalLength / speed;
    }

    const path = entity._fleePath;
    const elapsed = entity._stateElapsed - entity._fleeStart;
    let rawT = Math.min(elapsed / entity._fleeDur, 1);
    const t = this._easing ? this._easing(rawT) : rawT;
    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;

    if (t >= 1) {
      const ep = path.sampleAt(path.totalLength);
      entity.x = ep.x; entity.y = ep.y;
      entity.vx = 0; entity.vy = 0;
      entity._fleeArrived = true;
      return;
    }

    const pt = path.sampleAt(t * path.totalLength);
    const s = speed * accel;
    entity.vx = pt.tx * s;
    entity.vy = pt.ty * s;
    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(t);
      ox = pt.nx * d; oy = pt.ny * d;
    }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._fleePath = null;
    entity._fleeStart = null;
    entity._fleeDur = null;
    entity._fleeArrived = null;
  }
}


// ── cling (relational_nonpath) ──

export class Cling extends RelationalVerb {
  constructor() {
    super('cling', { gap: 0, collision: 'none' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 220;
    const elapsed = entity._stateElapsed ?? 0;

    if (!entity._clingArrived) {
      if (!entity._clingPath) {
        const dist = Math.hypot(t.x - entity.x, t.y - entity.y);
        const contactDist = entity.radius + t.radius;
        if (dist <= contactDist + 4) {
          entity._clingArrived = true;
          entity._clingOrbitAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
        } else {
          entity._clingPath = BezierPath.fromEndpoints(
            { x: entity.x, y: entity.y }, { x: t.x, y: t.y },
            { perpOffset: 0.2, side: Math.random() < 0.5 ? 1 : -1 }
          );
          entity._clingDur = entity._clingPath.totalLength / speed;
          entity._clingT0 = elapsed;
          entity._clingOriginEnd = entity._clingPath.sampleAt(entity._clingPath.totalLength);
        }
      }

      if (entity._clingPath) {
        let rawT = Math.min((elapsed - entity._clingT0) / entity._clingDur, 1);
        if (this._easing) rawT = this._easing(rawT);
        const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;

        const pt = entity._clingPath.sampleAt(rawT * entity._clingPath.totalLength);
        const driftX = t.x - entity._clingOriginEnd.x;
        const driftY = t.y - entity._clingOriginEnd.y;
        let ox = 0, oy = 0;
        if (this._offsetFn) { const d = this._offsetFn(rawT); ox = pt.nx * d; oy = pt.ny * d; }

        const pSpeed = (entity._clingPath.totalLength / entity._clingDur) * accel;
        entity.vx = pt.tx * pSpeed;
        entity.vy = pt.ty * pSpeed;
        entity.x = pt.x + driftX * rawT + ox - entity.vx * dt;
        entity.y = pt.y + driftY * rawT + oy - entity.vy * dt;

        if (rawT >= 1) {
          entity._clingArrived = true;
          entity._clingOrbitAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
          entity._clingPath = null;
        }
      }
    }

    if (entity._clingArrived) {
      this.lookAt(entity, dt, 24);
      const contactDist = entity.radius + t.radius;
      entity._clingOrbitAngle = (entity._clingOrbitAngle ?? 0) + 0.3 * dt;
      const goalX = t.x + Math.cos(entity._clingOrbitAngle) * contactDist;
      const goalY = t.y + Math.sin(entity._clingOrbitAngle) * contactDist;
      this.spring(entity, dt, goalX, goalY, 0.85);
      this.mirror(entity);
    }
  }

  cleanup(entity) {
    entity._clingPath = null;
    entity._clingDur = null;
    entity._clingT0 = null;
    entity._clingOriginEnd = null;
    entity._clingArrived = null;
    entity._clingOrbitAngle = null;
  }
}


// ── guard (relational_nonpath) ──

export class Guard extends RelationalVerb {
  constructor() {
    super('guard', { gap: 40, collision: 'stop' });
  }

  _ensurePath(entity) {
    if (entity._guardPath) return;
    const orbitR = this.bubble(entity) + 24;
    entity._guardOrbitR = orbitR;
    const N = 72;
    const points = [];
    for (let i = 0; i <= N; i++) {
      const a = (i / N) * Math.PI * 2;
      points.push({ x: Math.cos(a) * orbitR, y: Math.sin(a) * orbitR });
    }
    entity._guardPath = new Path(points);
    const t = entity._target;
    const startAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
    const frac = ((startAngle / (Math.PI * 2)) % 1 + 1) % 1;
    entity._guardStartDist = frac * entity._guardPath.totalLength;
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;

    if (this._wait && entity._stateElapsed < this._wait) {
      entity.vx = 0;
      entity.vy = 0;
      return;
    }

    this._ensurePath(entity);

    const path = entity._guardPath;
    const speed = this._adverbSpeed ?? 70;
    const elapsed = entity._stateElapsed - (this._wait ?? 0);
    const timeT = elapsed / (path.totalLength / speed || 1);
    const accel = this._accelerationFn ? this._accelerationFn(timeT % 1) : 1;
    const eased = this._easing ? this._easing(timeT % 1) : timeT;

    const dist = (entity._guardStartDist + eased * path.totalLength * accel) % path.totalLength;
    const pt = path.sampleAt(dist);

    let goalX = pt.x + t.x;
    let goalY = pt.y + t.y;

    if (this._offsetFn) {
      const normT = dist / path.totalLength;
      const off = this._offsetFn(normT);
      goalX += pt.nx * off;
      goalY += pt.ny * off;
    }

    const stiffness = 6;
    entity.vx = (goalX - entity.x) * stiffness;
    entity.vy = (goalY - entity.y) * stiffness;

    this.lookAway(entity, dt, 10);
  }

  cleanup(entity) {
    entity._guardPath = null;
    entity._guardOrbitR = null;
    entity._guardStartDist = null;
  }
}


// ── watch (relational_nonpath) ──

export class Watch extends RelationalVerb {
  constructor() {
    super('watch', { gap: 80, collision: 'stop' });
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;
    const t = entity._target;
    if (!t) return;

    this.lookAt(entity, dt, 10);

    const speed = this._adverbSpeed ?? 80;
    const watchDist = this.bubble(entity) + 60;
    const dx = t.x - entity.x, dy = t.y - entity.y;
    const dist = Math.hypot(dx, dy) || 0.01;
    const elapsed = entity._stateElapsed ?? 0;

    const needsReplan = !entity._watchPath ||
      (entity._watchArrived && Math.abs(dist - watchDist) > 50);

    if (needsReplan) {
      const nx = (entity.x - t.x) / dist, ny = (entity.y - t.y) / dist;
      const gx = Math.max(30, Math.min(482, t.x + nx * watchDist));
      const gy = Math.max(30, Math.min(482, t.y + ny * watchDist));
      const pDist = Math.hypot(gx - entity.x, gy - entity.y);
      if (pDist < 3) { entity._watchArrived = true; entity.vx = 0; entity.vy = 0; return; }
      entity._watchSide = (entity._watchSide || 1) * -1;
      entity._watchPath = BezierPath.fromEndpoints(
        { x: entity.x, y: entity.y }, { x: gx, y: gy },
        { perpOffset: 0.12, side: entity._watchSide }
      );
      entity._watchDuration = entity._watchPath.totalLength / speed;
      entity._watchStart = elapsed;
      entity._watchArrived = false;
    }

    const path = entity._watchPath;
    const dur = entity._watchDuration || 1;
    let rawT = Math.min((elapsed - (entity._watchStart || 0)) / dur, 1);
    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;
    if (this._easing) rawT = this._easing(rawT);

    if (rawT >= 1) {
      const ep = path.sampleAt(path.totalLength);
      entity.x = ep.x; entity.y = ep.y;
      entity.vx = 0; entity.vy = 0;
      entity._watchArrived = true;
      return;
    }

    const pt = path.sampleAt(rawT * path.totalLength);
    const pSpeed = (path.totalLength / dur) * accel;
    entity.vx = pt.tx * pSpeed;
    entity.vy = pt.ty * pSpeed;
    let ox = 0, oy = 0;
    if (this._offsetFn) { const d = this._offsetFn(rawT); ox = pt.nx * d; oy = pt.ny * d; }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._watchPath = null;
    entity._watchDuration = null;
    entity._watchStart = null;
    entity._watchArrived = null;
    entity._watchSide = null;
  }
}


// ── repel (relational_nonpath) ──

export class Repel extends RelationalVerb {
  constructor() {
    super('repel', { gap: 60, collision: 'none' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 180;
    const elapsed = entity._stateElapsed ?? 0;

    const awayAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
    const prevAngle = entity._repelAngle ?? awayAngle;
    const angleDelta = Math.abs(Math.atan2(Math.sin(awayAngle - prevAngle), Math.cos(awayAngle - prevAngle)));
    const pathDone = elapsed >= (entity._repelPathEnd ?? 0);

    if (!entity._repelPath || pathDone || angleDelta > Math.PI * 0.25) {
      this._buildPath(entity, t, speed, awayAngle);
    }

    const path = entity._repelPath;
    if (!path) return;

    const localT = elapsed - (entity._repelPathStart ?? 0);
    let rawT = Math.min(localT / (entity._repelDur || 1), 1);
    const easedT = this._easing ? this._easing(rawT) : rawT;
    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;
    const effectiveSpeed = speed * accel;

    const dist = easedT * path.totalLength;
    const pt = path.sampleAt(dist);

    entity.vx = pt.tx * effectiveSpeed;
    entity.vy = pt.ty * effectiveSpeed;

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(easedT);
      ox = pt.nx * d;
      oy = pt.ny * d;
    }

    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
    this.lookAway(entity, dt, 12);
  }

  _buildPath(entity, target, speed, awayAngle) {
    const margin = entity.radius + 10;
    const distToTarget = Math.hypot(entity.x - target.x, entity.y - target.y);
    const fleeLen = Math.max(100, Math.min(300, 320 - distToTarget * 0.4));

    let ex = entity.x + Math.cos(awayAngle) * fleeLen;
    let ey = entity.y + Math.sin(awayAngle) * fleeLen;

    ex = Math.max(margin, Math.min(512 - margin, ex));
    ey = Math.max(margin, Math.min(512 - margin, ey));

    const reachable = Math.hypot(ex - entity.x, ey - entity.y);
    if (reachable < fleeLen * 0.25) {
      const perp = ((entity._stateElapsed * 1000 | 0) % 2 === 0) ? 1 : -1;
      ex = entity.x + Math.cos(awayAngle + perp * Math.PI * 0.45) * fleeLen;
      ey = entity.y + Math.sin(awayAngle + perp * Math.PI * 0.45) * fleeLen;
      ex = Math.max(margin, Math.min(512 - margin, ex));
      ey = Math.max(margin, Math.min(512 - margin, ey));
    }

    const start = { x: entity.x, y: entity.y };
    const end = { x: ex, y: ey };
    const side = ((entity.x * 7 + entity.y * 13 | 0) % 2 === 0) ? 1 : -1;

    try {
      entity._repelPath = BezierPath.fromEndpoints(start, end, { perpOffset: 0.18, side });
    } catch (_) {
      entity._repelPath = Path.fromEndpoints(start, end);
    }

    const elapsed = entity._stateElapsed ?? 0;
    entity._repelDur = entity._repelPath.totalLength / speed;
    entity._repelPathStart = elapsed;
    entity._repelPathEnd = elapsed + entity._repelDur;
    entity._repelAngle = awayAngle;
  }

  cleanup(entity) {
    entity._repelPath = null;
    entity._repelDur = null;
    entity._repelPathStart = null;
    entity._repelPathEnd = null;
    entity._repelAngle = null;
  }
}


// ── hug (relational_nonpath) ──

export class Hug extends RelationalVerb {
  constructor() {
    super('hug', { gap: 0, collision: 'none' });
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;
    const t = entity._target;
    if (!t) return;

    if (!entity._hugPath) this._buildPath(entity, t);

    const elapsed = entity._stateElapsed ?? 0;
    const wait = this._wait ?? 0;
    const duration = entity._hugDuration;
    let rawT = elapsed < wait ? 0 : Math.min((elapsed - wait) / duration, 1);
    const easedT = this._easing ? this._easing(rawT) : (1 - Math.pow(1 - rawT, 2));

    const path = entity._hugPath;
    const pt = path.sampleAt(easedT * path.totalLength);

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(easedT);
      ox = pt.nx * d;
      oy = pt.ny * d;
    }

    const tdx = t.x - entity._hugTargetX0;
    const tdy = t.y - entity._hugTargetY0;

    if (rawT >= 1) {
      entity.x = pt.x + ox + tdx;
      entity.y = pt.y + oy + tdy;
      entity.vx = 0;
      entity.vy = 0;
      this.lookAt(entity, dt, 12);
      this.spring(entity, dt, t.x, t.y, 0.2);
    } else {
      const speed = path.totalLength / duration;
      const accel = this._accelerationFn ? this._accelerationFn(easedT) : 1;
      entity.vx = pt.tx * speed * accel;
      entity.vy = pt.ty * speed * accel;
      entity.x = pt.x + ox + tdx - entity.vx * dt;
      entity.y = pt.y + oy + tdy - entity.vy * dt;
      this.lookAt(entity, dt, 10);
    }
  }

  _buildPath(entity, t) {
    entity._hugTargetX0 = t.x;
    entity._hugTargetY0 = t.y;

    const startAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
    const dist = Math.hypot(t.x - entity.x, t.y - entity.y) || 1;
    const contactDist = entity.radius + t.radius;
    const arcSpan = Math.PI * 1.4;
    const side = 1;
    const points = [];

    for (let i = 0; i <= 10; i++) {
      const f = i / 10;
      const r = dist + (contactDist - dist) * f;
      const angle = startAngle + f * 0.15 * side;
      points.push({ x: t.x + Math.cos(angle) * r, y: t.y + Math.sin(angle) * r });
    }

    const arcStart = startAngle + 0.15 * side;
    for (let i = 1; i <= 24; i++) {
      const f = i / 24;
      const angle = arcStart + f * arcSpan * side;
      points.push({ x: t.x + Math.cos(angle) * contactDist, y: t.y + Math.sin(angle) * contactDist });
    }

    entity._hugPath = new Path(points);
    entity._hugDuration = entity._hugPath.totalLength / (this._adverbSpeed ?? 110);
  }

  cleanup(entity) {
    entity._hugPath = null;
    entity._hugDuration = null;
    entity._hugTargetX0 = null;
    entity._hugTargetY0 = null;
  }
}


// ── chase (relational_path) ──

export class Chase extends RelationalVerb {
  constructor() {
    super('chase', { gap: 6, collision: 'stop' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 220;
    const tNorm = (entity._stateElapsed ?? 0) / (entity._stateDuration || 1);
    const accel = this._accelerationFn ? this._accelerationFn(tNorm) : 1;
    const effSpeed = speed * accel;

    this.lookAt(entity, dt, 14);

    const replanDue = !entity._chasePath || (entity._chaseTimer ?? 0) <= 0 || entity._chaseT >= 1;
    if (replanDue) {
      const predX = t.x + (t.vx || 0) * 0.3, predY = t.y + (t.vy || 0) * 0.3;
      const dx = predX - entity.x, dy = predY - entity.y;
      const dist = Math.hypot(dx, dy), bub = this.bubble(entity);
      const ratio = dist > bub ? (dist - bub) / dist : 0;
      const gx = entity.x + dx * ratio, gy = entity.y + dy * ratio;
      const pDist = Math.hypot(gx - entity.x, gy - entity.y);
      if (pDist > 2) {
        entity._chaseSide = -(entity._chaseSide || -1);
        entity._chasePath = BezierPath.fromEndpoints(
          { x: entity.x, y: entity.y }, { x: gx, y: gy },
          { perpOffset: 0.12, side: entity._chaseSide }
        );
        entity._chaseDur = entity._chasePath.totalLength / effSpeed;
        entity._chaseStart = entity._stateElapsed;
      }
      entity._chaseTimer = 0.2;
      entity._chaseT = 0;
    }
    entity._chaseTimer -= dt;

    const path = entity._chasePath;
    if (!path) { this.attract(entity, dt, effSpeed); return; }

    let rawT = Math.min((entity._stateElapsed - (entity._chaseStart || 0)) / (entity._chaseDur || 1), 1);
    if (this._easing) rawT = this._easing(rawT);
    entity._chaseT = rawT;

    if (rawT >= 1) {
      const col = this.detectCollision(entity);
      if (!col || !col.hit) this.attract(entity, dt, effSpeed);
      else { entity.vx = 0; entity.vy = 0; }
      return;
    }

    const pt = path.sampleAt(rawT * path.totalLength);
    const spd = path.totalLength / (entity._chaseDur || 1);
    entity.vx = pt.tx * spd;
    entity.vy = pt.ty * spd;
    let ox = 0, oy = 0;
    if (this._offsetFn) { const d = this._offsetFn(rawT); ox = pt.nx * d; oy = pt.ny * d; }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._chasePath = null;
    entity._chaseDur = null;
    entity._chaseStart = null;
    entity._chaseTimer = null;
    entity._chaseSide = null;
    entity._chaseT = null;
  }
}


// ── orbit (relational_path) ──

export class Orbit extends RelationalVerb {
  constructor() {
    super('orbit', { gap: 20, collision: 'none' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;

    if (this._wait && entity._stateElapsed < this._wait) return;

    if (entity._orbitAngle == null) {
      const dx = entity.x - t.x;
      const dy = entity.y - t.y;
      entity._orbitAngle = Math.atan2(dy, dx);
    }

    const speed = this._adverbSpeed ?? 90;
    const radius = this.bubble(entity);

    const elapsed = entity._stateElapsed ?? 0;
    const dur = entity._stateDuration || 4;
    const tNorm = Math.min(elapsed / dur, 1);
    const accel = this._accelerationFn ? this._accelerationFn(tNorm) : 1;

    const omega = (speed * accel) / Math.max(radius, 1);
    entity._orbitAngle += omega * dt;

    let r = radius;
    if (this._offsetFn) {
      r += this._offsetFn(tNorm);
    }

    const goalX = t.x + Math.cos(entity._orbitAngle) * r;
    const goalY = t.y + Math.sin(entity._orbitAngle) * r;

    const tangentAngle = entity._orbitAngle + Math.PI / 2;
    const tangentSpeed = omega * r;
    entity.vx = Math.cos(tangentAngle) * tangentSpeed;
    entity.vy = Math.sin(tangentAngle) * tangentSpeed;

    entity.x = goalX - entity.vx * dt;
    entity.y = goalY - entity.vy * dt;

    this.lookAt(entity, dt, 12);
  }

  cleanup(entity) {
    entity._orbitAngle = null;
  }
}


// ── escort (relational_path) ──

export class Escort extends RelationalVerb {
  constructor() {
    super('escort', { gap: 6, collision: 'stop' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    if (entity._escortSide == null) {
      entity._escortSide = Math.random() < 0.5 ? 1 : -1;
      entity._escortPathT = 0;
      entity._escortAge = 0;
    }

    this.match(entity);
    this.lookAt(entity, dt, 10);

    const speed = this._adverbSpeed ?? 160;
    const normT = entity._stateElapsed / (entity._stateDuration || 1);
    const accel = this._accelerationFn ? this._accelerationFn(normT) : 1;
    const effSpeed = speed * accel;
    const bub = this.bubble(entity);
    const ori = entity._targetOrientation || Math.atan2(entity.y - t.y, entity.x - t.x);
    const angle = ori + entity._escortSide * Math.PI * 0.3;
    const pad = entity.radius;
    const gx = Math.max(pad, Math.min(512 - pad, t.x + Math.cos(angle) * bub));
    const gy = Math.max(pad, Math.min(512 - pad, t.y + Math.sin(angle) * bub));
    const distToGoal = Math.hypot(gx - entity.x, gy - entity.y);

    entity._escortAge = (entity._escortAge || 0) + dt;

    if (!entity._escortPath || entity._escortAge > 0.35 || entity._escortPathT >= 1) {
      if (distToGoal < 3) {
        this.mirror(entity);
        this.spring(entity, dt, gx, gy, 0.4);
        return;
      }
      entity._escortPath = BezierPath.fromEndpoints(
        { x: entity.x, y: entity.y }, { x: gx, y: gy },
        { perpOffset: 0.15, side: entity._escortSide }
      );
      entity._escortAge = 0;
      entity._escortPathT = 0;
    }

    const path = entity._escortPath;
    if (!path || path.totalLength < 1) { this.mirror(entity); return; }

    const dur = path.totalLength / effSpeed;
    entity._escortPathT = Math.min((entity._escortPathT || 0) + dt / dur, 1);
    let pT = this._easing ? this._easing(entity._escortPathT) : entity._escortPathT;

    if (pT >= 1) {
      this.mirror(entity);
      this.spring(entity, dt, gx, gy, 0.4);
      return;
    }

    const pt = path.sampleAt(pT * path.totalLength);
    const pSpeed = path.totalLength / dur;
    entity.vx = pt.tx * pSpeed;
    entity.vy = pt.ty * pSpeed;
    let ox = 0, oy = 0;
    if (this._offsetFn) { const d = this._offsetFn(pT); ox = pt.nx * d; oy = pt.ny * d; }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
  }

  cleanup(entity) {
    entity._escortPath = null;
    entity._escortPathT = null;
    entity._escortAge = null;
    entity._escortSide = null;
  }
}


// ── mirror (relational_path) ──

export class Mirror extends RelationalVerb {
  constructor() {
    super('mirror', { gap: 0, collision: 'none' });
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    const t = entity._target;
    if (!t) return;

    const cx = 256, cy = 256;
    const mirrorX = 2 * cx - t.x;
    const mirrorY = 2 * cy - t.y;

    const goalDrift = Math.hypot(mirrorX - (entity._mirrorGoalX ?? mirrorX),
                                  mirrorY - (entity._mirrorGoalY ?? mirrorY));
    const needsRebuild = !entity._mirrorPath || entity._mirrorArrived || goalDrift > 24;

    if (needsRebuild) {
      const dist = Math.hypot(mirrorX - entity.x, mirrorY - entity.y);
      entity._mirrorGoalX = mirrorX;
      entity._mirrorGoalY = mirrorY;
      if (dist > 2) {
        entity._mirrorSide = -(entity._mirrorSide || 1);
        entity._mirrorPath = BezierPath.fromEndpoints(
          { x: entity.x, y: entity.y },
          { x: mirrorX, y: mirrorY },
          { perpOffset: Math.min(0.3, 40 / dist), side: entity._mirrorSide }
        );
        const speed = this._adverbSpeed ?? 200;
        entity._mirrorDuration = entity._mirrorPath.totalLength / speed;
        entity._mirrorElapsed = 0;
        entity._mirrorArrived = false;
      } else {
        entity._mirrorPath = null;
        entity._mirrorArrived = true;
      }
    }

    if (!entity._mirrorPath) {
      entity.x = mirrorX;
      entity.y = mirrorY;
      entity.vx = 0;
      entity.vy = 0;
      this.lookAt(entity, dt, 6);
      return;
    }

    entity._mirrorElapsed += dt;
    const dur = entity._mirrorDuration || 1;
    const rawT = Math.min(entity._mirrorElapsed / dur, 1);
    const easedT = this._easing ? this._easing(rawT) : rawT;
    const accel = this._accelerationFn ? this._accelerationFn(rawT) : 1;

    const path = entity._mirrorPath;
    const point = path.sampleAt(easedT * path.totalLength);
    const baseSpeed = this._adverbSpeed ?? 200;
    const speed = baseSpeed * accel;

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(easedT);
      ox = point.nx * d;
      oy = point.ny * d;
    }

    entity.vx = point.tx * speed;
    entity.vy = point.ty * speed;
    entity.x = point.x + ox - entity.vx * dt;
    entity.y = point.y + oy - entity.vy * dt;

    if (rawT >= 1) {
      entity._mirrorArrived = true;
      entity.vx = 0;
      entity.vy = 0;
    }

    this.lookAt(entity, dt, 6);
  }

  cleanup(entity) {
    entity._mirrorPath = null;
    entity._mirrorGoalX = null;
    entity._mirrorGoalY = null;
    entity._mirrorSide = null;
    entity._mirrorDuration = null;
    entity._mirrorElapsed = null;
    entity._mirrorArrived = null;
  }
}


// ── weave (relational_path) ──

export class Weave extends RelationalVerb {
  constructor() {
    super('weave', { gap: 12, collision: 'stop' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 90;
    const elapsed = entity._stateElapsed ?? 0;
    const tNorm = elapsed / (entity._stateDuration || 1);
    const accel = this._accelerationFn ? this._accelerationFn(tNorm) : 1;
    const effSpeed = speed * accel;

    if (entity._weaveTraveled == null) {
      entity._weaveTraveled = 0;
      entity._weavePrevLat = 0;
      entity._weavePrevAdverb = 0;
    }

    const dx = t.x - entity.x;
    const dy = t.y - entity.y;
    const dist = Math.hypot(dx, dy) || 0.01;
    const bub = this.bubble(entity);

    if (dist <= bub) {
      this.resist(entity, dt, 6);
      return;
    }

    const fx = dx / dist, fy = dy / dist;
    const px = -fy, py = fx;

    const step = Math.min(effSpeed * dt, dist - bub);
    entity._weaveTraveled += step;

    const amp = 38, waveLen = 90;
    const phase = (entity._weaveTraveled / waveLen) * Math.PI * 2;
    const lateral = Math.sin(phase) * amp;
    const latDelta = lateral - entity._weavePrevLat;
    entity._weavePrevLat = lateral;

    let perpDelta = 0;
    if (this._offsetFn) {
      const off = this._offsetFn(tNorm);
      perpDelta = off - entity._weavePrevAdverb;
      entity._weavePrevAdverb = off;
    }

    const mx = fx * step + px * (latDelta + perpDelta);
    const my = fy * step + py * (latDelta + perpDelta);
    entity.x += mx;
    entity.y += my;

    if (dt > 0) {
      entity.vx = mx / dt;
      entity.vy = my / dt;
    }

    this.lookAt(entity, dt, 10);
  }

  cleanup(entity) {
    entity._weaveTraveled = null;
    entity._weavePrevLat = null;
    entity._weavePrevAdverb = null;
  }
}


// ── intercept (relational_path) ──

export class Intercept extends RelationalVerb {
  constructor() {
    super('intercept', { gap: 0, collision: 'stop' });
    this._replanInterval = 0.3;
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;

    const t = entity._target;
    if (!t) return;

    this.match(entity);

    const speed = this._adverbSpeed ?? 220;
    const elapsed = entity._stateElapsed ?? 0;
    const normT = elapsed / (entity._stateDuration || 3);
    const accel = this._accelerationFn ? this._accelerationFn(normT) : 1;
    const effectiveSpeed = speed * accel;

    const dx = t.x - entity.x;
    const dy = t.y - entity.y;
    const dist = Math.hypot(dx, dy);
    const timeToReach = dist / (effectiveSpeed || 1);

    let ix = t.x + (t.vx || 0) * timeToReach * 1.1;
    let iy = t.y + (t.vy || 0) * timeToReach * 1.1;
    const refineDist = Math.hypot(ix - entity.x, iy - entity.y);
    const refineTime = refineDist / (effectiveSpeed || 1);
    ix = t.x + (t.vx || 0) * refineTime;
    iy = t.y + (t.vy || 0) * refineTime;
    ix = Math.max(16, Math.min(496, ix));
    iy = Math.max(16, Math.min(496, iy));

    entity._interceptReplanTimer = (entity._interceptReplanTimer ?? 0) - dt;
    const drift = Math.hypot(ix - (entity._interceptIX ?? 0), iy - (entity._interceptIY ?? 0));
    const needsReplan = !entity._interceptPath ||
      entity._interceptReplanTimer <= 0 || drift > 50 ||
      (entity._interceptLocalT ?? 0) >= 1;

    if (needsReplan) {
      const start = { x: entity.x, y: entity.y };
      const end = { x: ix, y: iy };
      const cross = dx * (t.vy || 0) - dy * (t.vx || 0);
      const side = cross >= 0 ? 1 : -1;
      const curvature = Math.min(0.25, (entity._targetSpeed ?? 0) / 400);

      entity._interceptPath = BezierPath.fromEndpoints(start, end, {
        perpOffset: Math.max(0.05, curvature),
        side: side
      });
      entity._interceptLocalT = 0;
      entity._interceptIX = ix;
      entity._interceptIY = iy;
      entity._interceptReplanTimer = this._replanInterval;
      entity._interceptDur = entity._interceptPath.totalLength / (effectiveSpeed || 1);
    }

    const dur = entity._interceptDur || 1;
    entity._interceptLocalT = Math.min((entity._interceptLocalT ?? 0) + dt / dur, 1);

    let pathT = entity._interceptLocalT;
    if (this._easing) pathT = this._easing(pathT);

    const path = entity._interceptPath;
    const sample = path.sampleAt(pathT * path.totalLength);
    const pathSpeed = path.totalLength / dur;

    entity.vx = sample.tx * pathSpeed;
    entity.vy = sample.ty * pathSpeed;

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(pathT);
      ox = sample.nx * d;
      oy = sample.ny * d;
    }

    entity.x = sample.x + ox - entity.vx * dt;
    entity.y = sample.y + oy - entity.vy * dt;

    this.lookAt(entity, dt, 14);

    const col = this.detectCollision(entity);
    if (col && col.hit) {
      if (this.collision === 'stop') {
        entity.x += -col.nx * col.overlap;
        entity.y += -col.ny * col.overlap;
        entity.vx = 0;
        entity.vy = 0;
      } else if (this.collision === 'recoil') {
        entity.x += -col.nx * col.overlap;
        entity.y += -col.ny * col.overlap;
        entity.vx = -col.nx * effectiveSpeed * 0.4;
        entity.vy = -col.ny * effectiveSpeed * 0.4;
      }
    }
  }

  cleanup(entity) {
    entity._interceptPath = null;
    entity._interceptLocalT = null;
    entity._interceptIX = null;
    entity._interceptIY = null;
    entity._interceptReplanTimer = null;
    entity._interceptDur = null;
  }
}


// ── flank (relational_path) ──

export class Flank extends RelationalVerb {
  constructor() {
    super('flank', { gap: 10, collision: 'stop' });
    this._side = Math.random() < 0.5 ? 1 : -1;
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;
    const t = entity._target;
    if (!t) return;

    if (!entity._flankPath) this._buildPath(entity);

    const path = entity._flankPath;
    const dur = entity._flankDur;
    const elapsed = (entity._stateElapsed ?? 0) - (this._wait ?? 0);
    const rawT = Math.max(0, Math.min(elapsed / dur, 1));
    const eT = this._easing ? this._easing(rawT) : rawT;
    const accel = this._accelerationFn ? this._accelerationFn(eT) : 1;

    if (eT >= 1) {
      const ep = path.sampleAt(path.totalLength);
      entity.x = ep.x; entity.y = ep.y;
      entity.vx = 0; entity.vy = 0;
      this.lookAt(entity, dt);
      return;
    }

    const pt = path.sampleAt(eT * path.totalLength);
    const spd = (path.totalLength / dur) * accel;
    entity.vx = pt.tx * spd;
    entity.vy = pt.ty * spd;

    let ox = 0, oy = 0;
    if (this._offsetFn) {
      const d = this._offsetFn(eT);
      ox = pt.nx * d; oy = pt.ny * d;
    }
    entity.x = pt.x + ox - entity.vx * dt;
    entity.y = pt.y + oy - entity.vy * dt;
    this.lookAt(entity, dt, 10);
  }

  _buildPath(entity) {
    const t = entity._target;
    const bub = this.bubble(entity);
    const baseAngle = Math.atan2(entity.y - t.y, entity.x - t.x);
    const flankAngle = baseAngle + this._side * Math.PI * 0.55;
    const dest = {
      x: t.x + Math.cos(flankAngle) * bub,
      y: t.y + Math.sin(flankAngle) * bub
    };
    entity._flankPath = BezierPath.fromEndpoints(
      { x: entity.x, y: entity.y }, dest,
      { perpOffset: 0.4, side: this._side }
    );
    const speed = this._adverbSpeed ?? 170;
    entity._flankDur = entity._flankPath.totalLength / speed;
  }

  cleanup(entity) {
    entity._flankPath = null;
    entity._flankDur = null;
  }
}


// ── leapfrog (relational_path) ──

export class Leapfrog extends RelationalVerb {
  constructor() {
    super('leapfrog', { gap: 0, collision: 'none' });
  }

  update(entity, dt) {
    if (this._wait && entity._stateElapsed < this._wait) return;
    const t = entity._target;
    if (!t) return;

    if (entity._leapfrogPhase == null) {
      entity._leapfrogPhase = 'approach';
      entity._leapfrogTimer = 0;
      entity._leapfrogSide = 1;
    }

    const speed = this._adverbSpeed ?? 220;
    entity._leapfrogTimer += dt;
    const phase = entity._leapfrogPhase;

    if (phase === 'approach') {
      this.lookAt(entity, dt);
      const dist = Math.hypot(t.x - entity.x, t.y - entity.y);
      if (dist > this.bubble(entity) + 60) {
        this.attract(entity, dt, speed);
      } else {
        entity._leapfrogPhase = 'windup';
        entity._leapfrogTimer = 0;
      }
    } else if (phase === 'windup') {
      this.resist(entity, dt, 10);
      this.lookAt(entity, dt, 25);
      if (entity._leapfrogTimer > 0.12) {
        const dx = t.x - entity.x;
        const dy = t.y - entity.y;
        const dist = Math.hypot(dx, dy) || 1;
        const overshoot = dist + this.bubble(entity) + 30;
        entity._leapfrogSX = entity.x;
        entity._leapfrogSY = entity.y;
        entity._leapfrogEX = entity.x + (dx / dist) * overshoot;
        entity._leapfrogEY = entity.y + (dy / dist) * overshoot;
        entity._leapfrogSide *= -1;
        const tLen = Math.hypot(entity._leapfrogEX - entity._leapfrogSX, entity._leapfrogEY - entity._leapfrogSY);
        entity._leapfrogDur = tLen / speed;
        entity._leapfrogPhase = 'leap';
        entity._leapfrogTimer = 0;
      }
    } else if (phase === 'leap') {
      const dur = entity._leapfrogDur;
      const raw = Math.min(entity._leapfrogTimer / dur, 1);
      const accel = this._accelerationFn ? this._accelerationFn(raw) : 1;
      const prog = this._easing ? this._easing(raw) : raw;

      const sx = entity._leapfrogSX, sy = entity._leapfrogSY;
      const ex = entity._leapfrogEX, ey = entity._leapfrogEY;
      const tdx = ex - sx, tdy = ey - sy;
      const tLen = Math.hypot(tdx, tdy) || 1;
      const nx = -tdy / tLen, ny = tdx / tLen;
      const arcMag = Math.min(tLen * 0.45, 110) * entity._leapfrogSide;

      const bx = sx + tdx * prog;
      const by = sy + tdy * prog;
      const arcH = Math.sin(prog * Math.PI) * arcMag;
      const offset = this._offsetFn ? this._offsetFn(prog) : 0;
      const px = bx + nx * (arcH + offset);
      const py = by + ny * (arcH + offset);

      const dpdt = accel / dur;
      const vArc = Math.cos(prog * Math.PI) * Math.PI * arcMag * dpdt;
      entity.vx = tdx * dpdt + nx * vArc;
      entity.vy = tdy * dpdt + ny * vArc;
      entity.x = px - entity.vx * dt;
      entity.y = py - entity.vy * dt;
      entity.orientation = Math.atan2(entity.vy, entity.vx);

      if (raw >= 1) {
        entity.x = ex; entity.y = ey;
        entity.vx = 0; entity.vy = 0;
        entity._leapfrogPhase = 'land';
        entity._leapfrogTimer = 0;
      }
    } else if (phase === 'land') {
      this.resist(entity, dt, 12);
      this.lookAt(entity, dt, 8);
      if (entity._leapfrogTimer > 0.22) {
        entity._leapfrogPhase = 'windup';
        entity._leapfrogTimer = 0;
      }
    }
  }

  cleanup(entity) {
    entity._leapfrogPhase = null;
    entity._leapfrogTimer = null;
    entity._leapfrogSide = null;
    entity._leapfrogSX = null;
    entity._leapfrogSY = null;
    entity._leapfrogEX = null;
    entity._leapfrogEY = null;
    entity._leapfrogDur = null;
  }
}


// ── fight (relational_nonpath) ──

export class Fight extends RelationalVerb {
  constructor() {
    super('fight', { gap: 4, collision: 'recoil' });
  }

  update(entity, dt) {
    const t = entity._target;
    if (!t) return;
    if (this._wait && entity._stateElapsed < this._wait) return;

    const speed = this._adverbSpeed ?? 200;
    const accel = this._accelerationFn
      ? this._accelerationFn((entity._stateElapsed ?? 0) / (entity._stateDuration || 1))
      : 1;

    // Phase state: 'charge' → 'recoil' → 'charge' …
    if (!entity._fightPhase) {
      entity._fightPhase = 'charge';
      entity._fightTimer = 0;
    }

    entity._fightTimer += dt;
    const bub = this.bubble(entity);
    const dx = t.x - entity.x;
    const dy = t.y - entity.y;
    const dist = Math.hypot(dx, dy) || 1;
    const nx = dx / dist;
    const ny = dy / dist;

    if (entity._fightPhase === 'charge') {
      // Rush toward target
      entity.vx += nx * speed * accel * 6 * dt;
      entity.vy += ny * speed * accel * 6 * dt;
      entity.vx *= Math.exp(-2.5 * dt);
      entity.vy *= Math.exp(-2.5 * dt);

      // On contact, switch to recoil
      if (dist < bub + 4) {
        entity._fightPhase = 'recoil';
        entity._fightTimer = 0;
        // Impact kick
        entity.vx = -nx * speed * 0.8;
        entity.vy = -ny * speed * 0.8;
      }
    } else {
      // Recoil: drift back briefly, then re-engage
      entity.vx *= Math.exp(-4 * dt);
      entity.vy *= Math.exp(-4 * dt);

      if (entity._fightTimer > 0.25) {
        entity._fightPhase = 'charge';
        entity._fightTimer = 0;
      }
    }

    this.lookAt(entity, dt, 14);
  }

  cleanup(entity) {
    entity._fightPhase = null;
    entity._fightTimer = null;
  }
}


